const STRAPI_URL = process.env.STRAPI_URL ?? 'http://localhost:1337';
const STRAPI_TOKEN = process.env.STRAPI_API_TOKEN!;

interface StrapiArticle {
  id: number;
  documentId: string;
  title: string;
  slug: string;
  content: string;
  publishedAt: string | null;
  cover: {
    url: string;
    alternativeText: string | null;
  } | null;
}

interface StrapiListResponse<T> {
  data: T[];
  meta: {
    pagination: {
      page: number;
      pageSize: number;
      pageCount: number;
      total: number;
    };
  };
}

async function getArticles(page = 1, pageSize = 10): Promise<StrapiArticle[]> {
  const params = new URLSearchParams({
    'pagination[page]': String(page),
    'pagination[pageSize]': String(pageSize),
    'populate[cover][fields][0]': 'url',
    'populate[cover][fields][1]': 'alternativeText',
    'sort[0]': 'publishedAt:desc',
  });

  const response = await fetch(`${STRAPI_URL}/api/articles?${params}`, {
    headers: {
      Authorization: `Bearer ${STRAPI_TOKEN}`,
      'Content-Type': 'application/json',
    },
    next: { revalidate: 60 }, // Next.js ISR cache hint
  });

  if (!response.ok) {
    throw new Error(`Strapi fetch failed: ${response.status} ${response.statusText}`);
  }

  const json: StrapiListResponse<StrapiArticle> = await response.json();
  return json.data;
}

const articles = await getArticles(1, 10);
console.log('Articles:', articles);

const STRAPI_URL = process.env.STRAPI_URL ?? 'http://localhost:1337';
const STRAPI_TOKEN = process.env.STRAPI_API_TOKEN!;

interface CreateArticleInput {
  title: string;
  slug: string;
  content: string;
  publishedAt?: string; // set to null to create as draft
}

interface StrapiCreateResponse {
  data: {
    id: number;
    documentId: string;
    title: string;
    slug: string;
    content: string;
    publishedAt: string | null;
    createdAt: string;
    updatedAt: string;
  };
}

async function createArticle(input: CreateArticleInput): Promise<StrapiCreateResponse['data']> {
  const response = await fetch(`${STRAPI_URL}/api/articles`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${STRAPI_TOKEN}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      data: {
        title: input.title,
        slug: input.slug,
        content: input.content,
        publishedAt: input.publishedAt ?? null, // null = draft, ISO string = published
      },
    }),
  });

  if (!response.ok) {
    const error = await response.json();
    throw new Error(`Failed to create article: ${JSON.stringify(error)}`);
  }

  const json: StrapiCreateResponse = await response.json();
  console.log('Created article with ID:', json.data.id, 'documentId:', json.data.documentId);
  return json.data;
}

await createArticle({
  title: 'My First Article',
  slug: 'my-first-article',
  content: 'This is the body of the article.',
  publishedAt: new Date().toISOString(), // publish immediately
});
